window.PORTAL={lessons:[
{n:1,title:'「人が動ける言葉」とは何か',phase:-1,intro:'伝え方の手前には、考え方と感じ方があります。これから学ぶことを、まず一つの全体像として見渡します。',bridge:'第2〜4回で自分と相手の感じ方を理解し、第5〜6回で問題とビジョンを言葉にします。その材料を使って対話するのが、第7回です。'},
{n:2,title:'自分マネジメント',phase:0,intro:'怒りや不安の奥には、素朴な期待や願いがあります。自分の感情を受け止め、本当に伝えたかったことを見つけます。',bridge:'ここで扱う感情は、第3回の「自分の軸」、第5〜6回の「問題意識・あるべき姿」の材料になります。'},
{n:3,title:'自分の軸',phase:0,intro:'「こうしたい」「これは嫌だ」。自分の内側にある感覚を言葉にして、自分の軸の出発点を見つけます。',bridge:'自分のわがままを大切にすると、相手にも相手のわがままがあるとわかる。その関わり方を第4回で、組織のビジョンへのつながりを第6回で扱います。'},
{n:4,title:'他者の尊重と自分軸のバランス',phase:0,intro:'自分の軸を持ちながら、相手を決めつけない。見えている行動の奥に、相手なりの感じ方や考え方があることを捉えます。',bridge:'相手の内側を「わかったつもり」にせず、確認する余地をつくる。この姿勢を、第7回の雲・雨・傘と前提の確認で具体的な対話にします。'},
{n:5,title:'問題解決',phase:1,intro:'漠然とした困りごとを、取り組める問題へ。自分の違和感も手がかりに、現状と理想のギャップを捉え直します。',bridge:'第1〜4回で見つめてきた感情や個性を、問題設定に使います。現状の解像度を上げたら、第6回では「自分が本当に望む姿」を深めます。'},
{n:6,title:'課題の深掘りと私のビジョン',phase:1,intro:'本当に解決したいのは、何だろう。自分の本音と組織の中で実現したい姿をつなぎ、問題の捉え方を深めます。',bridge:'第2回の一次感情、第3回のわがまま、第5回の問題設定がここで合流します。生まれたビジョンを相手と確かめ合うのが、第7回です。'},
{n:7,title:'建設的なコミュニケーション',phase:2,intro:'自分と相手の違いを、対話の中で確かめる。雲・雨・傘と隠れた前提を手がかりに、次の行動を一緒につくります。',bridge:'第1回の「違いを明らかにする」、第4回の「相手の内側は見えない」、第6回の「私のビジョン」が、具体的な対話の方法につながります。'}
],cards:[
{id:'three-perspectives',lesson:1,slide:6,title:'感じる・考える・伝える',summary:'「どう伝えるか」の前に、自分の内側で起きていること。講座全体の見取り図です。',body:['人が動ける言葉になるまでには、三つの段階があります。どう伝えるか。その前に、どう考えるか。さらにその前に、どう感じるかがあります。話す順番だけを整えても、自分が何をしたいのかが言葉になっていなければ、相手が動ける説明にはなりません。','私たちは、仕事を回すことに追われると、行動の前にあった感情や思考を意識しなくなります。「やるからやる」になりやすいんですね。自分が現実をどう捉え、何を感じ、だから何をしたいと思ったのか。そこを言葉にすることから、この講座は始まります。'],links:[]},
{id:'different-views',lesson:1,slide:9,title:'対話で、違いを明らかにする',summary:'意見が対立したら、その手前へ。見ている事実や解釈の違いを確かめます。',body:['私たちは「こうしよう」というアクションプランのところで話をしがちです。でも、その前には、見ている状況や事実、それをどう捉えたか、だから何をしたいのかという流れがあります。相手にも、相手なりの流れがあります。','「私はこういう背景があって、これをしようと思った。あなたには、そういう背景があるんですね」。そんなふうに、キャッチボールの中で違いを明らかにしていきます。見ている現実が違うなら確認し、解釈が違うならその理由を聞く。行動の結論だけでぶつかる前に、戻れる場所を持つということです。'],links:[]},
{id:'overlap',lesson:1,slide:21,title:'組織の方針と、自分の思いの重なり',summary:'義務や役割と、自分がやりたいこと。その重なりに、この組織での自分のビジョンがあります。',body:['組織の中には、義務・役割・責任があります。一方、自分の中には「これがやりたい」「これは嫌だ」「ここに問題意識がある」という感覚があります。忙しかったり、プレッシャーがかかったりすると、義務や責任のほうが前に出やすくなります。','だから、自分の感じ方を言葉にして、組織から求められていることと重なる部分を探します。「やらなければならない」だけでなく、「だからこそ、自分もここをやりたい」と思えるところです。その重なりが見つかると、この組織で何をゴールにし、どんな方針で働きかけたいかを考えられるようになります。'],links:[]}
]};
window.PORTAL.cards.push(
{id:'accept-emotions',lesson:2,slide:8,title:'感情を受け止める',summary:'「そう感じた自分」を認めると、本当に伝えたかったことを見つけやすくなります。',body:['自分をマネジメントするというと、感情をコントロールすることだと思われるかもしれません。この講座で大事にしているのは、自分の感情を受け入れることです。理性や常識が強く働きすぎているなら、「そこまで強く言わなくてもいいよ」と少し緩めてみます。','怒っている、不安になっている。まずは「自分の中にあるよね」と認めます。ただ、その気持ちをそのまま相手にぶつけると、関係がこじれやすくなります。受け止めることと、相手にぶつけることは分けて考えてください。','さらに、感情の奥にある素朴な期待・希望・願望を見ていきます。そこに気づくと、自分が本当に伝えたいことや、やりたいことの動機が見えてきます。'],links:[]},
{id:'primary-emotions',lesson:2,slide:15,title:'悔しさの奥にあった、本当の願い',summary:'お客様からの質問を「否定された」と受け取った失敗談。反応の奥にある願いを見つめます。',body:['コンサルタントになって間もないころ、私がまとめた提案をお客様に説明したときのことです。お客様は少し渋い顔をして、質問をされました。私はそれを「賛同してもらえなかった」と受け取り、悔しさや屈辱を感じて、さらに説明を重ねてしまいました。','でも、あとで聞くと、お客様は大枠では賛同していて、細かいところを確認したかっただけだったそうです。相手が聞きたいことを受け取れず、自分の説明を続けてしまったんですね。','その悔しさの奥には、「経験が十分でなくても、お客様の課題解決の役に立ちたい」「私を受け入れてほしい」という希望や願望がありました。講座でいう一次感情は、こうした素朴な期待や願いです。表に出た気持ちを手がかりに、その奥まで見ていきます。'],links:[]},
{id:'emotion-to-dialogue',lesson:2,slide:16,title:'本音がわかると、関わり方が変わる',summary:'「もっと説明しなきゃ」から「何が気になっていますか？」へ。感情の理解が対話につながります。',body:['「納得してもらえるように準備したのに」と悔しさだけを見ていたとき、私が選んだのは、もっとロジカルに説明することでした。でも、自分が本当に望んでいたのは、お客様の役に立ち、一緒に仕事をすることです。','そこに気づけると、「お客様が気にされているのは、どこですか？」と聞く余裕が生まれます。自分の説明を重ねることから、相手に関心を向け、キャッチボールすることへ、行動が変わります。','一次感情を見る意味は、気持ちに名前をつけるだけではありません。自分が本当に望んでいたことを踏まえて、次の関わり方を選べるようになることです。'],links:[]},
{id:'wagamama',lesson:3,slide:8,title:'「わがまま」は、自分の軸の出発点',summary:'「したい」「したくない」「こうありたい」。自分特有の感覚を、主体性の材料にします。',body:['この講座でいう「わがまま」は、あるがままの私、自分らしさや個性のことです。「これがしたい」「これは嫌だ」「こうありたい」。そういう自分の内側から出てくる感覚を見ていきます。','スーパーで子どもが「これ買って！」と騒ぐ場面を考えてみてください。その物が欲しいという気持ち自体は、その子の素直な気持ちです。一方、買ってくれない不満を公共の場でぶつけられると、周りは困ります。欲しいという願いと、それをどう表すかを、一緒くたにしないことが大事です。','自分の中の「やりたい」「嫌だ」にも、素朴な期待や願いが含まれています。それを言葉にすることが、自分の軸を見つける出発点になります。'],links:[]},
{id:'both-matter',lesson:3,slide:14,title:'自分らしさも、役割も大切にする',summary:'組織から求められることと、自分の内側の感覚。両方を見ることで、軸を取り戻します。',body:['仕事では、会社の理念や方針、義務・役割・責任が言葉になっています。上司との面談でも「今期はこれを期待しています」と伝えられます。だから、普段の判断は、外から与えられた基準を頼りにしやすいんです。','一方、自分らしい感じ方や、何が嫌で何をやりたいのかは、自分の中にしかありません。当たり前すぎて、わざわざ言葉にする機会も少ない。外の基準ばかりを優先すると、こちらが見えにくくなります。','社会や組織の一員として必要なことも、自分の感じ方も、どちらも大事です。葛藤が起こったときには、自分の感情に向き合い、「本当は何を大切にしたかったのか」を確かめてみてください。'],links:[]},
{id:'individuality-to-vision',lesson:3,slide:16,title:'個性を活かした先に、ビジョンがある',summary:'自分らしい行動が積み重なり、周囲に与える影響が広がる。その先にあるビジョンを考えます。',body:['自分が楽しい、やりたいと思えることは、行動に移しやすく、続けやすいものです。その感じ方や考え方を活かして行動を重ねると、できることや、周囲に与える影響も変わっていきます。','図では、個性、強み、ビジョン、志を同じ流れの中に置いています。自分のことから、周囲の人との関係、会社や組織、社会へ。誰にどんな影響を与えたいのかという範囲が広がっていきます。','最初から大きなビジョンを持たなければいけないわけではありません。自分のわがままを軸に、行動としてアウトプットを重ねる。その先で、どんな組織や社会を望むのかが見えてきます。'],links:[]},
{id:'black-box',lesson:4,slide:7,title:'相手の内側は、見えていない',summary:'言葉や行動の奥にある感情・思考・動機。自分にも相手にもある、見えない部分に目を向けます。',body:['相手の発言や行動は見えます。でも、その前に何を感じ、何を考え、何を望んだのかは見えません。自分にも感情や思考があるように、相手にも相手の内側があります。','私も日記を書く機会をかなり多く持っています。それでも、仕事を続けて気づいたら夕方、という日には、その間にどう感じ、どう考えたのかが残っていないことがあります。自分の内側さえ、言葉にしていなければ見えにくいんですね。','すると、相手にも見えない内側があることに意識が向かず、「こう考えているはずだ」と自分の想像で埋めてしまいます。表面的な情報のやり取りから一歩進むには、この見えていない部分の存在を認めることが必要です。'],links:[]},
{id:'leave-room',lesson:4,slide:11,title:'決めつける前に、確認する余地をつくる',summary:'「その行動にも、大事にしている何かがあるとしたら？」。相手を見るときの姿勢です。',body:['自分には理解しにくい行動を見ると、「やる気がない」「協力する気がない」と意味づけたくなることがあります。でも、その意味づけは、こちらの感じ方や考え方から出てきたものです。','いったん、「その行動が、何かを大事にしているから出ているのだとしたら？」と考えてみます。相手の価値観を言い当てることが目的ではありません。こちらの解釈で決めきらず、相手に確認できる余地をつくるための問いです。','自分の見え方を持ちながら、相手にはどう見えているのかを聞いてみる。その往復を重ねることが、信頼関係を築くコミュニケーションにつながります。'],links:[]},
{id:'respect-boundaries',lesson:4,slide:17,title:'尊重しながら、必要なことを伝える',summary:'相手の気持ちや価値観への関心と、行動への働きかけを両立します。',body:['相手のやりたい気持ち、考え、大事にしている価値観や経験には、関わり続けます。同時に、人に迷惑がかかる言動や、一方的な要求まで受け入れる必要はありません。安全やチームの成果を損なう行動には、対応が必要です。','自分のわがままを大切にすることは、組織のルールや役割をないがしろにすることではありません。自分らしさと義務・役割・責任の両方を大事にするのと同じように、相手への尊重と、必要な働きかけも両方大切です。','伝えるときには、「私はこの現状を見て、こう解釈し、こう感じました。だから、こうしてほしいと思っています」と、自分の見え方と希望を言葉にします。その上で、相手の考えも聞いていきます。'],links:[]},
{id:'gap',lesson:5,slide:5,title:'問題は、現状と理想のギャップ',summary:'何に困っているのかは、どんな状態を望むのかとセットで見えてきます。',body:['問題は、あるべき姿や理想と、現状の間のギャップです。普段は理想を意識せずに仕事をしているので、問題が突然起こったように感じます。でも、何かを嫌だ、困ったと感じるとき、その手前には自分なりの「こうあってほしい」があります。','例えば「体重が昔より10キロ増えた」だけでは、本当の困りごとはまだはっきりしません。お気に入りの服が着られないのか、健康診断の再検査が嫌なのか。それによって、どんな状態を望むのかも変わります。数字があるだけで、問題が具体的になるわけではないんですね。','この講座では、その中から解くべき問題を「課題」と呼びます。解決できる、または解決しやすく、解決への効果も大きいものへと絞っていきます。'],links:[]},
{id:'resolution',lesson:5,slide:11,title:'現場を知り、視座を一歩広げる',summary:'自分の仕事の範囲を少し広げて見ると、問題の捉え方も、解決策も変わります。',body:['機器のレンタル・リース会社で、営業と事務の間の受注情報のやり取りを扱ったことがあります。連絡は電話、メール、口頭、手書きメモとさまざま。足りない情報を確認し直す手間がかかっていました。','最初に出てきた改善案は、「メモを速く取る」「電話の当番を工夫する」といったものでした。自分の担当範囲で入力漏れを防ぐことを理想にすると、解決策もその範囲にとどまりやすいんです。','現場の人に聞く、行動を観察する、自分も当事者になってみる。他社や他業界、新しく入ってきた人の視点も参考になります。自分の責任範囲の一歩外まで関心を持つことで、どこに働きかければよいのかが見えてきます。'],links:[]},
{id:'ten-steps',lesson:5,slide:13,title:'問題を定義し直す、10のステップ',summary:'現状と気持ちを書き出し、問題を細かく捉える。第6回まで続く、問題設定の道筋です。',body:['いきなり解決策を探す前に、まずは現状を書き出し、そこで感じた気持ちに向き合います。何に困っているのかを定義し、問題を細分化し、現状の解像度を上げていきます。第5回では、この前半を扱いました。','一つの大きな問題に見えていても、細かく見ると、困っていることがいくつも混ざっている場合があります。先ほどの体重の例でも、「10キロ増えた」から「お気に入りの服が着られない」へと捉え直すと、切実な困りごとが具体的になります。','続く第6回では、自分の本音、あるべき姿、誰の役に立ちたいか、どんな状態でありたいかを確認します。そこまで考えると、最初に置いた問題そのものを、もう一度定義し直すことができます。'],links:[]},
{id:'true-wish',lesson:6,slide:10,title:'不満の奥の「本当はどうしたかった？」',summary:'第2回の一次感情を、問題設定に使うところです。不満を入口に、本音を見つけます。',body:['本当にその問題を解決したいのか。ここでは、自分の本音を確認します。入口は、不満や不安で構いません。「面倒だ」「やりたくない」と思う自分を受け止め、そこから、何がそう感じさせているのかを言葉にしていきます。','第2回で扱った一次感情が、ここで出てきます。「本当は、こうしたかっただけなのに」「こうしてほしかっただけなのに」。表に出た怒りや不安の奥にある、素朴な期待や希望です。','誰かに見せる文章を整えるつもりではなく、自分の気持ちを十分に吐き出してみてください。「あれ、私、何をやっていたんだっけ」と少し緩んだときに、ぽろっと漏れる本音がある。その願いが、次にあるべき姿を考える材料になります。'],links:[]},
{id:'vision-line',lesson:6,slide:19,title:'自分の個性と、あるべき姿をつなぐ',summary:'第3回で見つけた自分らしさを、「誰の役に、どう立ちたいか」へ広げます。',body:['第3回では、自分が夢中になること、苦もなくできること、時間を忘れて取り組むことから、自分らしい感じ方や行動の仕方を言葉にしました。今回は、その自分らしさを活かして、誰の役に立ち、どんな状態をつくりたいかを考えています。','例えば「自分が入力漏れをしない」から「営業も含めて受注内容を正確に共有する」、さらに「効率的な受注プロセスをつくる」へ。あるべき姿の高さを変えることは、誰の役に立つかを広げることでもあります。','個性とビジョンは、同じ直線上にあるものとして考えられます。ただ、一度決めたら固定する必要はありません。少し先の姿を仮置きし、行動してみて、「もう少しこっちだった」と見直してよいんです。'],links:[]},
{id:'my-vision',lesson:6,slide:23,title:'そのビジョンも、私の「わがまま」',summary:'組織のために考えた理想にも、自分の見方が含まれています。ここが対話への接続点です。',body:['自分が印象を受けた出来事と、心の底から「こうあってほしい」と思うこと。その間にあるギャップに働きかけ、組織や社会を理想に近づけようとする。そこに、自分のビジョンがあります。','組織の方針と重なっていたとしても、それは、私が考える、私にとってのあるべき姿です。相手も自分と同じように望んでいるとは限りません。自分の個性や私情が含まれていることを、自覚しておきたいんですね。','だからこそ、自分の思いを持って相手と話す必要があります。この「私にとっての理想」という実感が、次の第7回で、相手の見方にも関心を向ける土台になります。'],links:[]},
{id:'cloud-rain-umbrella',lesson:7,slide:12,title:'雲・雨・傘で、話の手前を見えるように',summary:'事実、推測・解釈、判断・提案を分けると、省略されていたことを確認できます。',body:['「空に雲が出ている」が事実。「雨が降りそうだ」が、事実を踏まえた推測・解釈。「傘を持っていこう」が、その推測を踏まえた判断・提案です。この三つを分けると、話の中で省略されているところが見つけやすくなります。','例えば「パソコンが動かないんですけど」と言われても、相手に何をしてほしいのかはわかりません。直してほしいのか、担当者を教えてほしいのか、仕事を別の人に頼んでほしいのか。事実だけでは、次の行動が決められないんですね。','自分の考えを整理するのと同時に、相手の雲・雨・傘も確認します。どの事実を見て、どう捉えて、だから何をしたいのか。第1回から話してきたキャッチボールを、具体的な形にする道具です。'],links:[]},
{id:'hidden-premises',lesson:7,slide:21,title:'同じ言葉でも、前提が違う',summary:'「来週まで」は月曜の朝？ 金曜まで？ 言葉の裏にある当たり前を確かめます。',body:['金曜日に「来週までに資料を作っておいて」と頼んだとします。頼んだ側は、来週月曜日の朝にはできているつもり。でも、受けた側は、一週間後の金曜日までだと思っていた。同じ言葉を共有していても、こうしたすれ違いが起こります。','それぞれにとって、「来週まで」という言葉を受け取るルールが違うんですね。自分には当たり前なので、そのルールが言葉に出てこない。このような、話の間にある隠れた前提に注意します。','雲・雨・傘をそろえても、うまく伝わらないことがあります。そのときは、自分が省略した当たり前はないか、相手には自分から見えていない前提がないかを確かめます。'],links:[]},
{id:'whole-person',lesson:7,slide:28,title:'気持ちも含めて、相手と関わる',summary:'確認が尋問にならないために。言葉の整理と、相手の気持ちを受け止めることを一緒に行います。',body:['雲・雨・傘は便利ですが、相手の話をすぐに「事実は？ 根拠は？」と詰めると、尋問のようになってしまいます。講義の質疑でも、この点を扱いました。相手が気持ちを話しているときには、まず「ああ、しんどくなっているんだね」と受け取ってください。','例えば「遅れそう」という言葉には、状況を見た推測と、不安や焦りが重なっていることがあります。その気持ちを聞き、落ち着いたところで、今どうなっているのかを一緒に確かめます。気持ちを聞くことと、事実や解釈を整理することの両方が必要です。','自分にも相手にも、感情や価値観、組織の中での役割があります。その丸ごとで関わりながら、「私はこう考えたけれど、あなたはどうですか」と確かめ合う。ここまで学んできた自分理解と他者尊重が、この対話につながっています。'],links:[]}
);
const connect=(a,b,forward,backward)=>{window.PORTAL.cards.find(c=>c.id===a).links.push({id:b,why:forward});window.PORTAL.cards.find(c=>c.id===b).links.push({id:a,why:backward})};
